async () => { /* D0 baseline: globals declared, runtime installed, guard registered with its door mappings before the carriages load, no stop yet; install the toast spy and record t0 */ window.__toasts = window.__toasts || []; if (!window.__toastSpy) { window.__toastSpy = true; const orig = window.gameAlert; window.gameAlert = (...a) => { window.__toasts.push({ t: Date.now(), a }); return orig ? orig(...a) : undefined; }; } const G = window.gameState.globalVariables; const R = window.deductionRuntime; window.__t0 = Date.now(); const guard = window.npcManager && window.npcManager.npcs && window.npcManager.npcs.get('ded_d_guard');
  const sus = ['ded_d_sato','ded_d_chen','ded_d_devries','ded_d_volkov','ded_d_mensah'];
  return !!R && !!guard && G.d_stop_1 === false && G.d_last_stop === false && G.mission_failed === '' && G.deduction_closed === false
    && sus.every(x => G['deduction_verdict_' + x] === '' && G['deduction_outcome_' + x] === '')
    && ['d_sato_pass','d_chen_charm','d_devries_sim'].every(f => G['deduction_faded_' + f] === false);  }

async () => { /* D1 stop 1 ran from the timer: d_sato_pass faded (first not held), state.faded lists it, the tamper toast showed, the guard opened car 2 */ const G = window.gameState.globalVariables; const R = window.deductionRuntime; await new Promise(r => setTimeout(r, 1500)); const st = R.getState().state;
  return G.deduction_faded_d_sato_pass === true && JSON.stringify(st.faded) === '["d_sato_pass"]' && G.se_intel_d_sato_pass === false
    && window.__toasts.some(x => JSON.stringify(x.a).includes('a clue you had not found yet has gone with it'))
    && (window.gameState.unlockedRooms || []).includes('d_car2');  }

async () => { /* D4 five 'final' verdicts, all right; the debrief shows in place on the same board; no outcome toasts (reveal end) */ await new Promise(r => setTimeout(r, 1000)); const st = window.deductionRuntime.getState().state; const v = st.verdicts; const ids = Object.keys(v); const mg = window.MinigameFramework.currentMinigame; const s = mg.getTestState();
  return ids.length === 5 && ids.every(k => v[k].kind === 'final') && v.ded_d_sato.outcome === 'right_guilty' && v.ded_d_chen.outcome === 'right_clear' && v.ded_d_devries.outcome === 'right_guilty' && v.ded_d_volkov.outcome === 'right_guilty' && v.ded_d_mensah.outcome === 'right_clear'
    && st.closed === true && st.debriefPending === true && s.board.view === 'debrief'
    && /Evidence destroyed|destroyed/i.test(mg.container.textContent) && /recovered/i.test(mg.container.textContent);  }

async () => { /* D4 Finish: d_case_solved and d_case_closed completed; mission_failed empty; credits under 'CASE CLOSED' with the right-call lines; ticker reads CASE CLOSED … NIGHT TRAIN; no MISSION COMPLETE anywhere */ await new Promise(r => setTimeout(r, 4000)); const om = window.objectivesManager; const h = document.querySelector('.bv-title-block h1'); const tk = document.querySelector('.bv-ticker-inner'); const body = document.body.textContent;
  return om.taskIndex.d_case_solved.status === 'completed' && om.taskIndex.d_case_closed.status === 'completed' && window.gameState.globalVariables.mission_failed === ''
    && !!h && /CASE CLOSED/.test(h.textContent) && !!tk && /CASE CLOSED/.test(tk.textContent) && /NIGHT TRAIN/.test(tk.textContent)
    && /Dmitri Volkov was named/.test(body) && !/MISSION COMPLETE/.test(body);  }
